def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    # The common color inside the tiles.
    interior = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Tile-boundary rows have very few interior-colored cells.
    boundary_rows = []
    for r, row in enumerate(grid):
        if sum(v == interior for v in row) <= 0.2 * w:
            boundary_rows.append(r)

    # Find the color of the lines between tiles using non-boundary rows.
    nonrows = [r for r in range(h) if r not in boundary_rows]
    counts = Counter(grid[r][c] for r in nonrows for c in range(w)
                     if grid[r][c] != interior)
    line = counts.most_common(1)[0][0] if counts else interior

    # Vertical tile boundaries are the columns carrying the line color
    # throughout the non-boundary rows.
    boundary_cols = [
        c for c in range(w)
        if nonrows and sum(grid[r][c] == line for r in nonrows) >= 0.7 * len(nonrows)
    ]

    out = []
    for r1, r2 in zip(boundary_rows, boundary_rows[1:]):
        row = []
        for c1, c2 in zip(boundary_cols, boundary_cols[1:]):
            corners = [grid[r1][c1], grid[r1][c2],
                       grid[r2][c1], grid[r2][c2]]
            if corners[0] == corners[1] == corners[2] == corners[3] and corners[0] != line:
                row.append(corners[0])
            else:
                row.append(interior)
        out.append(row)
    return out
